import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    m = int(data[0])
    n = int(data[1])

    if m <= 0 or n <= 0:
        print(-1)
        return

    grid = []
    index = 2
    for i in range(m):
        row = list(map(int, data[index:index+n]))
        grid.append(row)
        index += n

    dp = [[0] * n for _ in range(m)]
    dp[0][0] = grid[0][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    print(dp[m-1][n-1])

if __name__ == "__main__":
    main()
